var hook = $('Status Webhook').first().json;
var d = hook.body || hook;
var who = ($('Verify Staff').first().json || {}).body || {};
var allowed = ['new','confirmed','preparing','ready_for_pickup','out_for_delivery','delivered','completed','cancelled','declined'];
var status = String(d.status || '').trim();
var orderNum = String(d.order_number || '').trim();
if (orderNum === '' || allowed.indexOf(status) === -1) {
  return [{ json: { error: true, reason: 'Invalid order_number or status' } }];
}
var prep = parseInt(d.prep_minutes, 10);
if (isNaN(prep) || prep <= 0) { prep = 0; }
return [{ json: { order_number: orderNum, status: status, prep_minutes: prep,
                  reason: String(d.reason || d.declined_reason || ''),
                  staff: String(d.agent_name || d.accepted_by || who.email || 'staff'),
                  silent: d.silent === true, error: false } }];

var rows = $('Update Status').first().json;
var order = Array.isArray(rows) ? (rows[0] || null) : rows;
if (order && typeof order === 'object' && Object.keys(order).length === 0) { order = null; }
if (!order || !order.customer_phone) { return [{ json: { skip: true } }]; }

var ex = $('Extract Data').first().json;
var name = order.customer_name ? (' ' + String(order.customer_name).split(' ')[0]) : '';
var firstName = order.customer_name ? String(order.customer_name).split(' ')[0] : 'Guest';
var num = order.order_number || '';
var status = ex.status;
var prep = ex.prep_minutes || order.prep_minutes || 0;
var eta = prep ? ('\n\nReady in about ' + prep + ' minutes.') : '';
var dine = order.order_type === 'dine-in';
var reason = ex.reason || order.declined_reason || '';
var amt = Number(order.total || 0);

// Free-form messages only reach someone who messaged us in the last 24h
// (WhatsApp platform rule) - outside that window an approved Utility
// template is the only way it can reach them, for ANY status, not just
// the initial confirmation.
var recentRows = [];
try {
  var chk = $('Check Recent Inbound').first().json;
  var body = (chk && chk.body !== undefined) ? chk.body : chk;
  recentRows = Array.isArray(body) ? body : (body ? [body] : []);
} catch (e) { recentRows = []; }
var hasRecentInbound = recentRows.some(function (r) { return r && r.id; });

if (status === 'confirmed' || status === 'preparing') {
  var imgUrl = 'https://staff.brightmedia.tech/webhook/friedking-receipt?order_number=' + encodeURIComponent(num) + '&key=fk_bWzKMd0MI4U3WEUCAGYlQxcb';
  var caption = 'Your order ' + num + ' is confirmed!' + eta;

  var outgoing;
  if (hasRecentInbound) {
    outgoing = { type: 'image', image: { link: imgUrl, caption: caption } };
  } else {
    outgoing = { type: 'template', template: { name: 'friedking_order_confirmed', language: { code: 'en' },
      components: [
        { type: 'header', parameters: [ { type: 'image', image: { link: imgUrl } } ] },
        { type: 'body', parameters: [
            { type: 'text', text: firstName },
            { type: 'text', text: num },
            { type: 'text', text: String(amt) }
        ] }
      ] } };
  }
  return [{ json: { skip: false, phone: String(order.customer_phone), order_number: num, status: status, via_template: !hasRecentInbound, outgoing: outgoing } }];
}

if (status === 'out_for_delivery') {
  var outgoing2;
  if (hasRecentInbound) {
    outgoing2 = { type: 'text', text: { body: 'Good news' + name + '! Your order *' + num + '* is on its way.\nPlease keep Rs ' + amt + ' ready in cash for the rider.' } };
  } else {
    outgoing2 = { type: 'template', template: { name: 'friedking_order_out_for_delivery', language: { code: 'en' },
      components: [ { type: 'body', parameters: [
          { type: 'text', text: firstName },
          { type: 'text', text: num },
          { type: 'text', text: String(amt) }
      ] } ] } };
  }
  return [{ json: { skip: false, phone: String(order.customer_phone), order_number: num, status: status, via_template: !hasRecentInbound, outgoing: outgoing2 } }];
}

if (status === 'ready_for_pickup') {
  var detail = dine
    ? ('It is on its way to your table (Table ' + (order.table_number || '') + ').')
    : 'Please collect it from Arista Enclave, Ground Floor, 2nd Main Rd, Pandeshwar, Mangaluru, Karnataka 575001.';
  var outgoing3;
  if (hasRecentInbound) {
    outgoing3 = { type: 'text', text: { body: dine
      ? ('Your order *' + num + '* is ready and coming to table ' + (order.table_number || '') + '.')
      : ('Hi' + name + ', your order *' + num + '* is ready for pickup at Arista Enclave, Ground Floor, 2nd Main Rd, Pandeshwar, Mangaluru, Karnataka 575001.') } };
  } else {
    outgoing3 = { type: 'template', template: { name: 'friedking_order_ready', language: { code: 'en' },
      components: [ { type: 'body', parameters: [
          { type: 'text', text: num },
          { type: 'text', text: detail }
      ] } ] } };
  }
  return [{ json: { skip: false, phone: String(order.customer_phone), order_number: num, status: status, via_template: !hasRecentInbound, outgoing: outgoing3 } }];
}

if (status === 'declined' || status === 'cancelled') {
  var situation = status === 'declined'
    ? ('we were unable to take this order right now' + (reason ? (' (Reason: ' + reason + ')') : '') + '.')
    : 'this order has been cancelled by the restaurant.';
  var outgoing4;
  if (hasRecentInbound) {
    outgoing4 = { type: 'text', text: { body: status === 'declined'
      ? ('Hi' + name + ', we are sorry — we could not take order *' + num + '* right now.' +
          (reason ? ('\nReason: ' + reason) : '') +
          '\n\nPlease call +91 97421 75222 and we will sort it out for you.')
      : ('Hi' + name + ', your order *' + num + '* has been cancelled by the restaurant.\nPlease call +91 97421 75222 if this is unexpected.') } };
  } else {
    outgoing4 = { type: 'template', template: { name: 'friedking_order_update', language: { code: 'en' },
      components: [ { type: 'body', parameters: [
          { type: 'text', text: num },
          { type: 'text', text: situation }
      ] } ] } };
  }
  return [{ json: { skip: false, phone: String(order.customer_phone), order_number: num, status: status, via_template: !hasRecentInbound, outgoing: outgoing4 } }];
}

// 'delivered' intentionally has no message here - the post-delivery rating
// ask was dropped (cost with no captured value, nothing read the replies).
// Loyalty earning for this status is handled by a database trigger
// (trg_loyalty_on_order_status), not from this workflow.
return [{ json: { skip: true } }];
